import{_t as e,it as t,n,rt as r}from"./chunks/framework.BIpRff3v.js";var i=JSON.parse(`{"title":"0002. Tailwind v4 with logical-property utilities only","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/0002-tailwind-v4-logical-properties.md","filePath":"decisions/0002-tailwind-v4-logical-properties.md"}`),a={name:`decisions/0002-tailwind-v4-logical-properties.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="_0002-tailwind-v4-with-logical-property-utilities-only" tabindex="-1" dir="auto">0002. Tailwind v4 with logical-property utilities only <a class="header-anchor" href="#_0002-tailwind-v4-with-logical-property-utilities-only" aria-label="Permalink to “0002. Tailwind v4 with logical-property utilities only”">​</a></h1><ul><li dir="auto">Status: accepted</li><li dir="auto">Date: 2026-09-22</li></ul><h2 id="context" tabindex="-1" dir="auto">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p dir="auto">Most sites built from this template are Hebrew RTL, while shared components should also work LTR.</p><h2 id="decision" tabindex="-1" dir="auto">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p dir="auto">Style with Tailwind v4. Design tokens live in <code>libs/ui/src/styles.css</code> (<code>@theme</code>), and every app imports that file. Only logical utilities are allowed (<code>ms/me</code>, <code>ps/pe</code>, <code>start/end</code>, <code>text-start/end</code>, ...); ESLint rejects physical ones.</p><h2 id="consequences" tabindex="-1" dir="auto">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li dir="auto">Components flip automatically with <code>dir</code>.</li><li dir="auto">The lint rule matches class strings in TSX, so classes built dynamically from fragments (for example <code>&#39;m&#39; + side</code>) can slip past it. Avoid building class names that way.</li></ul>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};